effect.shader:
#define iTime (holoEvolution + (holoAnimate ? acTime * holoSpeed : 0.0))
#define iResolution vec3(acScreenSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acScreenSize * 0.5, 0.0, 0.0)
void gmGeneratedMainImage( out vec4 fragColor, in vec2 fragCoord )
{
float time = iTime;
vec2 uv = 0.5 * (2. * fragCoord.xy - iResolution.xy) / iResolution.y;
float displaceAmp = holoDisplace;
float displaceFreq = holoDisplaceFreq;
uv += vec2(displaceAmp * sin(time + uv.x * displaceFreq));
float horizon = holoHorizon * cos(time);
float fov = holoFov + holoFovSwing * sin(time);
float scaling = holoScale;
vec3 p = vec3(uv.x, fov, uv.y - horizon);
vec2 s = vec2(p.x/p.z, p.y/p.z) * scaling;
float oscFreq = 12.;
float oscAmp = holoWobble;
s += vec2(oscAmp * sin(time + s.x * oscFreq));
float color = max(
smoothstep(0.2, 0.8, 1. - pow(sin(s.y * holoGridDensity), 0.28)),
smoothstep(0.2, 0.8, 1. - pow(sin(s.x * holoGridDensity), 0.28))
);
color *= p.z * p.z * 10.0;
fragColor = vec4(holoColor.rgb * color, 1.0);
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acScreenNorm*acScreenSize);
vec4 gmSource=texture2DCv(inputImg.texture,acScreenNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
}
